dataSet.query:
ВЫБРАТЬ РАЗРЕШЕННЫЕ ДанныеКалендаря.Дата КАК Дата, ДанныеКалендаря.ВидДня КАК ВидДня ПОМЕСТИТЬ _ДниСверок ИЗ РегистрСведений.ДанныеКалендаря КАК ДанныеКалендаря ГДЕ ДанныеКалендаря.Календарь = ЗНАЧЕНИЕ(Справочник.Календари.Общероссийский) И ДанныеКалендаря.Дата МЕЖДУ &ДатаНачала И &ДатаОкончания ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ РАЗРЕШЕННЫЕ ЗНАЧЕНИЕ(Справочник.ВнешниеСистемы.ЖурналПодтвержденийОпераций) КАК Основание, "Сверка наличия подтверждающих документов" КАК ВидСверки ПОМЕСТИТЬ _ВидСверкиПоОснованию
ОБЪЕДИНИТЬ ВСЕ
ВЫБРАТЬ ЗНАЧЕНИЕ(Справочник.ВнешниеСистемы.СводныйОтчетОбОстаткахНаБанковскихСчетах), "Денежные средства на расчетных счетах"
ОБЪЕДИНИТЬ ВСЕ
ВЫБРАТЬ ЗНАЧЕНИЕ(Справочник.ВнешниеСистемы.ОтчетБрокераБКРегион), "Денежные средства у брокера БК Регион"
ОБЪЕДИНИТЬ ВСЕ
ВЫБРАТЬ ЗНАЧЕНИЕ(Справочник.ВнешниеСистемы.ОтчетБрокераГПБ), "Денежные средства у брокера ГПБ" ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ РАЗРЕШЕННЫЕ РАЗЛИЧНЫЕ СчетаДоверительногоУправления.Организация КАК Организация, СчетаДоверительногоУправления.Ссылка КАК СчетДоверительногоУправления, _ДниСверок.Дата КАК Дата, _ДниСверок.ВидДня КАК ВидДня ПОМЕСТИТЬ _ДниСверокКлиентов ИЗ _ДниСверок КАК _ДниСверок ВНУТРЕННЕЕ СОЕДИНЕНИЕ Справочник.СчетаДоверительногоУправления КАК СчетаДоверительногоУправления ПО (СчетаДоверительногоУправления.Организация = &Организация) И (СчетаДоверительногоУправления.ПометкаУдаления = ЛОЖЬ) И (СчетаДоверительногоУправления.ДатаЗаключения <= &ДатаОкончания) И _ДниСверок.Дата >= СчетаДоверительногоУправления.ДатаЗаключения И (СчетаДоверительногоУправления.ДатаРасторжения = ДАТАВРЕМЯ(1, 1, 1) ИЛИ СчетаДоверительногоУправления.ДатаРасторжения > &ДатаОкончания) И (НЕ СчетаДоверительногоУправления.КодСчета В (&КодыИсключаемыхПортфелей)) ЛЕВОЕ СОЕДИНЕНИЕ РегистрСведений.ЛицензииДоговоровДоверительногоУправления КАК ЛицензииДоговоровДоверительногоУправления ВНУТРЕННЕЕ СОЕДИНЕНИЕ (ВЫБРАТЬ ЛицензииДоговоровДоверительногоУправления.СчетДоверительногоУправления КАК СчетДоверительногоУправления, _ДниСверок.Дата КАК Дата, МАКСИМУМ(ЛицензииДоговоровДоверительногоУправления.Период) КАК ДатаИзменения ИЗ РегистрСведений.ЛицензииДоговоровДоверительногоУправления КАК ЛицензииДоговоровДоверительногоУправления ВНУТРЕННЕЕ СОЕДИНЕНИЕ _ДниСверок КАК _ДниСверок ПО (_ДниСверок.Дата >= ЛицензииДоговоровДоверительногоУправления.Период)
СГРУППИРОВАТЬ ПО ЛицензииДоговоровДоверительногоУправления.СчетДоверительногоУправления, _ДниСверок.Дата) КАК ИзмененияЛицензий ПО (ИзмененияЛицензий.СчетДоверительногоУправления = ЛицензииДоговоровДоверительногоУправления.СчетДоверительногоУправления) И (ИзмененияЛицензий.ДатаИзменения = ЛицензииДоговоровДоверительногоУправления.Период) И (ЛицензииДоговоровДоверительногоУправления.Действует) ПО (ЛицензииДоговоровДоверительногоУправления.СчетДоверительногоУправления = СчетаДоверительногоУправления.Ссылка) И (ИзмененияЛицензий.Дата = _ДниСверок.Дата) {ГДЕ (СчетаДоверительногоУправления.Ссылка = &СчетДоверительногоУправления), (ЛицензииДоговоровДоверительногоУправления.Лицензия.ВидДеятельности = &ВидДеятельности), (НЕ(&СкрыватьСобственныеСчета И СчетаДоверительногоУправления.ВидДоговораДоверительногоУправления = ЗНАЧЕНИЕ(Перечисление.ВидыДоговоровДоверительногоУправления.Собственный)))} ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ РАЗРЕШЕННЫЕ _ДниСверокКлиентов.Организация КАК Организация, _ДниСверокКлиентов.СчетДоверительногоУправления КАК СчетДоверительногоУправления, _ДниСверокКлиентов.Дата КАК Дата, ЗНАЧЕНИЕ(Справочник.ВнешниеСистемы.ЖурналПодтвержденийОпераций) КАК Основание ПОМЕСТИТЬ _ПлановыеСверкиКлиентов ИЗ _ДниСверокКлиентов КАК _ДниСверокКлиентов ГДЕ _ДниСверокКлиентов.ВидДня В (ЗНАЧЕНИЕ(Перечисление.ВидыДнейКалендаря.Рабочий), ЗНАЧЕНИЕ(Перечисление.ВидыДнейКалендаря.Предпраздничный))
ОБЪЕДИНИТЬ ВСЕ
ВЫБРАТЬ _ДниСверокКлиентов.Организация, _ДниСверокКлиентов.СчетДоверительногоУправления, _ДниСверокКлиентов.Дата, ЗНАЧЕНИЕ(Справочник.ВнешниеСистемы.СводныйОтчетОбОстаткахНаБанковскихСчетах) ИЗ _ДниСверокКлиентов КАК _ДниСверокКлиентов ГДЕ _ДниСверокКлиентов.ВидДня В (ЗНАЧЕНИЕ(Перечисление.ВидыДнейКалендаря.Рабочий), ЗНАЧЕНИЕ(Перечисление.ВидыДнейКалендаря.Предпраздничный))
ОБЪЕДИНИТЬ ВСЕ
ВЫБРАТЬ РАЗЛИЧНЫЕ _ДниСверокКлиентов.Организация, _ДниСверокКлиентов.СчетДоверительногоУправления, _ДниСверокКлиентов.Дата, ВЫБОР КОГДА КодыКлиентовУБрокеров.Брокер = &БрокерГПБ ТОГДА ЗНАЧЕНИЕ(Справочник.ВнешниеСистемы.ОтчетБрокераГПБ) КОГДА КодыКлиентовУБрокеров.Брокер = &БрокерБКРегион ТОГДА ЗНАЧЕНИЕ(Справочник.ВнешниеСистемы.ОтчетБрокераБКРегион) ИНАЧЕ "Отчет брокера " + КодыКлиентовУБрокеров.Брокер.Наименование КОНЕЦ ИЗ _ДниСверокКлиентов КАК _ДниСверокКлиентов ВНУТРЕННЕЕ СОЕДИНЕНИЕ РегистрСведений.КодыСчетовДоверительногоУправленияУБрокеров КАК КодыКлиентовУБрокеров ВНУТРЕННЕЕ СОЕДИНЕНИЕ (ВЫБРАТЬ КодыКлиентовУБрокеров.Организация КАК Организация, КодыКлиентовУБрокеров.СчетДоверительногоУправления КАК СчетДоверительногоУправления, КодыКлиентовУБрокеров.Брокер КАК Брокер, КодыКлиентовУБрокеров.ДоговорБрокерскогоОбслуживания КАК ДоговорБрокерскогоОбслуживания, _ДниСверокКлиентов.Дата КАК Дата, МАКСИМУМ(КодыКлиентовУБрокеров.Период) КАК ДатаИзменения, МАКСИМУМ(УсловияДоговоровОбщие.Период) КАК ПериодУсловийДоговора ИЗ РегистрСведений.КодыСчетовДоверительногоУправленияУБрокеров КАК КодыКлиентовУБрокеров ВНУТРЕННЕЕ СОЕДИНЕНИЕ _ДниСверокКлиентов КАК _ДниСверокКлиентов ПО (_ДниСверокКлиентов.Организация = КодыКлиентовУБрокеров.Организация) И (_ДниСверокКлиентов.СчетДоверительногоУправления = КодыКлиентовУБрокеров.СчетДоверительногоУправления) И (_ДниСверокКлиентов.ВидДня В (ЗНАЧЕНИЕ(Перечисление.ВидыДнейКалендаря.Рабочий), ЗНАЧЕНИЕ(Перечисление.ВидыДнейКалендаря.Предпраздничный))) И (_ДниСверокКлиентов.Дата >= КодыКлиентовУБрокеров.Период) ЛЕВОЕ СОЕДИНЕНИЕ РегистрСведений.УсловияДоговоровОбщие КАК УсловияДоговоровОбщие ПО (УсловияДоговоровОбщие.Договор = КодыКлиентовУБрокеров.ДоговорБрокерскогоОбслуживания) И (_ДниСверокКлиентов.Дата >= УсловияДоговоровОбщие.Период)
СГРУППИРОВАТЬ ПО КодыКлиентовУБрокеров.Организация, КодыКлиентовУБрокеров.СчетДоверительногоУправления, КодыКлиентовУБрокеров.Брокер, КодыКлиентовУБрокеров.ДоговорБрокерскогоОбслуживания, _ДниСверокКлиентов.Дата) КАК ИзменениеБрокеровКлиентов ПО (ИзменениеБрокеровКлиентов.Организация = КодыКлиентовУБрокеров.Организация) И (ИзменениеБрокеровКлиентов.СчетДоверительногоУправления = КодыКлиентовУБрокеров.СчетДоверительногоУправления) И (ИзменениеБрокеровКлиентов.Брокер = КодыКлиентовУБрокеров.Брокер) И (ИзменениеБрокеровКлиентов.ДоговорБрокерскогоОбслуживания = КодыКлиентовУБрокеров.ДоговорБрокерскогоОбслуживания) И (ИзменениеБрокеровКлиентов.ДатаИзменения = КодыКлиентовУБрокеров.Период) ЛЕВОЕ СОЕДИНЕНИЕ РегистрСведений.УсловияДоговоровОбщие КАК УсловияДоговоровОбщие ПО (УсловияДоговоровОбщие.Договор = ИзменениеБрокеровКлиентов.ДоговорБрокерскогоОбслуживания) И (УсловияДоговоровОбщие.Период = ИзменениеБрокеровКлиентов.ПериодУсловийДоговора) ПО (КодыКлиентовУБрокеров.Организация = _ДниСверокКлиентов.Организация) И (КодыКлиентовУБрокеров.СчетДоверительногоУправления = _ДниСверокКлиентов.СчетДоверительногоУправления) И (ИзменениеБрокеровКлиентов.Дата = _ДниСверокКлиентов.Дата) И (УсловияДоговоровОбщие.ДатаРасторжения ЕСТЬ NULL ИЛИ УсловияДоговоровОбщие.ДатаРасторжения = ДАТАВРЕМЯ(1, 1, 1) ИЛИ УсловияДоговоровОбщие.ДатаРасторжения > _ДниСверокКлиентов.Дата) ГДЕ _ДниСверокКлиентов.ВидДня В (ЗНАЧЕНИЕ(Перечисление.ВидыДнейКалендаря.Рабочий), ЗНАЧЕНИЕ(Перечисление.ВидыДнейКалендаря.Предпраздничный))
ОБЪЕДИНИТЬ ВСЕ
ВЫБРАТЬ РАЗЛИЧНЫЕ _ДниСверокКлиентов.Организация, _ДниСверокКлиентов.СчетДоверительногоУправления, _ДниСверокКлиентов.Дата, ВЫБОР КОГДА ИсполнителиПоЦеннымБумагам.ДепозитарныйСчет.Депозитарий = &ДепозитарийБКРегион ТОГДА ЗНАЧЕНИЕ(Справочник.ВнешниеСистемы.ОтчетДепозитарияБКРегион) КОГДА ИсполнителиПоЦеннымБумагам.ДепозитарныйСчет.Депозитарий = &ДепозитарийДКРегион ТОГДА ЗНАЧЕНИЕ(Справочник.ВнешниеСистемы.ОтчетДепозитарияДКРегион) КОГДА ИсполнителиПоЦеннымБумагам.ДепозитарныйСчет.Депозитарий = &ДепозитарийНСД ТОГДА ЗНАЧЕНИЕ(Справочник.ВнешниеСистемы.ОтчетДепозитарияНСД) КОГДА ИсполнителиПоЦеннымБумагам.ДепозитарныйСчет.Депозитарий = &ДепозитарийИнфинитум ТОГДА ЗНАЧЕНИЕ(Справочник.ВнешниеСистемы.ОтчетДепозитарияИнфинитум) КОГДА ИсполнителиПоЦеннымБумагам.ДепозитарныйСчет.Депозитарий = &ДепозитарийВТБ ТОГДА ЗНАЧЕНИЕ(Справочник.ВнешниеСистемы.ОтчетДепозитарияВТБ) КОГДА ИсполнителиПоЦеннымБумагам.ДепозитарныйСчет.Депозитарий = &ДепозитарийГПБ ТОГДА ЗНАЧЕНИЕ(Справочник.ВнешниеСистемы.ОтчетДепозитарияГПБ) КОГДА ИсполнителиПоЦеннымБумагам.ДепозитарныйСчет.Депозитарий = &ДепозитарийРСД ТОГДА ЗНАЧЕНИЕ(Справочник.ВнешниеСистемы.ОтчетДепозитарияСбербанка) КОГДА ИсполнителиПоЦеннымБумагам.ДепозитарныйСчет.Депозитарий = &ДепозитарийНФОТехнологии ТОГДА ЗНАЧЕНИЕ(Справочник.ВнешниеСистемы.ОтчетДепозитарияНФОТехнологии) ИНАЧЕ "Отчет депозитария " + ИсполнителиПоЦеннымБумагам.ДепозитарныйСчет.Депозитарий.Наименование КОНЕЦ ИЗ _ДниСверокКлиентов КАК _ДниСверокКлиентов ВНУТРЕННЕЕ СОЕДИНЕНИЕ РегистрСведений.ИсполнителиПоЦеннымБумагам КАК ИсполнителиПоЦеннымБумагам ПО (ИсполнителиПоЦеннымБумагам.Организация = _ДниСверокКлиентов.Организация) И (ИсполнителиПоЦеннымБумагам.СчетДоверительногоУправления = _ДниСверокКлиентов.СчетДоверительногоУправления) И (ИсполнителиПоЦеннымБумагам.ДатаЗакрытия = ДАТАВРЕМЯ(1, 1, 1) ИЛИ ИсполнителиПоЦеннымБумагам.ДатаЗакрытия > _ДниСверокКлиентов.Дата) И (ИсполнителиПоЦеннымБумагам.ДепозитарныйСчет.ДатаОткрытия = ДАТАВРЕМЯ(1, 1, 1) ИЛИ ИсполнителиПоЦеннымБумагам.ДепозитарныйСчет.ДатаОткрытия <= _ДниСверокКлиентов.Дата) ВНУТРЕННЕЕ СОЕДИНЕНИЕ (ВЫБРАТЬ МАКСИМУМ(ДанныеКалендаря.Дата) КАК Дата, КОНЕЦПЕРИОДА(ДанныеКалендаря.Дата, НЕДЕЛЯ) КАК КонецНедели ИЗ РегистрСведений.ДанныеКалендаря КАК ДанныеКалендаря ВНУТРЕННЕЕ СОЕДИНЕНИЕ Константа.ОсновнойКалендарьКотировок КАК ОсновнойКалендарьКотировок ПО ДанныеКалендаря.Календарь = ОсновнойКалендарьКотировок.Значение ГДЕ ДанныеКалендаря.ВидДня В (ЗНАЧЕНИЕ(Перечисление.ВидыДнейКалендаря.Рабочий), ЗНАЧЕНИЕ(Перечисление.ВидыДнейКалендаря.Предпраздничный)) И ДЕНЬНЕДЕЛИ(ДанныеКалендаря.Дата) <= 5
